const SAMPLE = [{"id":"FB-1001","customer":"Nordhafen Logistics","customer_tier":"strategic","source":"support_ticket","received_at":"2026-10-27T08:14:00Z","text":"Since the last quarterly update the Manage Billing Documents app takes over 40 seconds to load for our billing clerks. We process about 2,300 invoices a day and month-end close is in two weeks. Please call me back on +49 170 1234567. Regards, Jonas Weber"},{"id":"FB-1002","customer":"Brightfield Foods","customer_tier":"standard","source":"survey","received_at":"2026-10-27T09:02:00Z","text":"The new guided buying flow is much easier for our occasional requesters. Approval times dropped noticeably."},{"id":"FB-1003","customer":"Vantara Chemicals","customer_tier":"strategic","source":"interview","received_at":"2026-10-28T13:30:00Z","text":"We need a way to simulate the impact of intercompany price changes before posting. Today our controllers export everything to Excel, which takes two days each quarter."},{"id":"FB-1004","customer":"Orbis Medical","customer_tier":"standard","source":"community","received_at":"2026-10-28T15:45:00Z","text":"Is there any documentation on how to extend the purchase requisition with custom fields? The help page just links to a 404, which is frustrating."},{"id":"FB-1005","customer":"Kestrel Mobility","customer_tier":"strategic","source":"email","received_at":"2026-10-29T07:20:00Z","text":"Our IDoc interface to the warehouse system fails silently: deliveries are created in ERP but never reach the WMS. We only notice when customers complain about missing shipments. Contact: m.schulz@kestrel-mobility.example"},{"id":"FB-1006","customer":"Lumen Retail Group","customer_tier":"standard","source":"survey","received_at":"2026-10-29T10:05:00Z","text":"Dashboards look nice, but I cannot filter the margin analysis by store cluster, so I still build that report manually every Monday."},{"id":"FB-1007","customer":"Tessaro Machinery","customer_tier":"strategic","source":"support_ticket","received_at":"2026-10-30T06:50:00Z","text":"The MRP run creates duplicate planned orders for components with multiple BOM alternatives. Our production planners delete hundreds of them manually every morning before the shift starts."},{"id":"FB-1008","customer":"Brightfield Foods","customer_tier":"standard","source":"email","received_at":"2026-10-30T11:12:00Z","text":"Licensing for our seasonal workers is too expensive. They only need read access to their payslips for three months a year. Thanks, Anna"},{"id":"FB-1009","customer":"Orbis Medical","customer_tier":"standard","source":"interview","received_at":"2026-10-31T09:40:00Z","text":"Supplier master data has many duplicates after the migration. The same vendor exists three times with different bank details, one of them DE89 3704 0044 0532 0130 00. Our auditors flagged this."},{"id":"FB-1010","customer":"Vantara Chemicals","customer_tier":"strategic","source":"survey","received_at":"2026-11-02T08:00:00Z","text":"Great job on the new financial close cockpit. Our team can see every open task in one place and the close is now one day faster."},{"id":"FB-1011","customer":"Lumen Retail Group","customer_tier":"standard","source":"community","received_at":"2026-11-02T14:25:00Z","text":"Would love an API to push store sales into the ERP in near real time instead of the nightly batch file."},{"id":"FB-1012","customer":"Nordhafen Logistics","customer_tier":"strategic","source":"email","received_at":"2026-11-03T08:30:00Z","text":"Since the last quarterly update the Manage Billing Documents app takes over 40 seconds to load for our billing clerks. We process about 2,300 invoices a day and month-end close is in two weeks. Please call me back on +49 170 1234567. Regards, Jonas Weber"}];
return SAMPLE.map((json) => ({ json }));

// Accepts demo items, a single webhook payload, or a webhook batch ({ items: [...] }).
// Emits one clean record per feedback entry and drops exact duplicates within the batch.
const SOURCES = ['survey', 'support_ticket', 'interview', 'community', 'email'];
const TIERS = ['strategic', 'standard'];

const raw = [];
for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  if (Array.isArray(body.items)) raw.push(...body.items);
  else raw.push(body);
}

const seen = new Set();
const out = [];
for (const r of raw) {
  const text = String(r.text ?? r.feedback ?? '').trim();
  if (!text) continue;
  const customer = String(r.customer ?? r.customer_id ?? 'unknown');
  const key = `${customer}::${text.toLowerCase().replace(/\s+/g, ' ')}`;
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({
    json: {
      feedback_id: String(r.id ?? r.feedback_id ?? `FB-${Date.now()}-${out.length}`),
      customer,
      customer_tier: TIERS.includes(r.customer_tier) ? r.customer_tier : 'standard',
      source: SOURCES.includes(r.source) ? r.source : 'email',
      received_at: r.received_at ?? new Date().toISOString(),
      text,
    },
  });
}
return out;

// Data minimisation: personal data is removed BEFORE any text is sent to the LLM.
// Only the redacted text travels downstream; the original is not forwarded.
const PATTERNS = [
  { label: '[EMAIL]', re: /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi },
  { label: '[IBAN]', re: /\b[A-Z]{2}\d{2}(?:\s?[A-Z0-9]{4}){3,7}(?:\s?[A-Z0-9]{1,3})?\b/g },
  { label: '[PHONE]', re: /(?:\+|\b00?)\d[\d\s\-\/().]{6,}\d/g, minDigits: 9 },
];
const SIGN_OFF = /\b([Mm]y name is|[Rr]egards,?|[Cc]heers,?|[Tt]hanks,?|[Bb]est,?)\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)/g;

const redact = (text) => {
  let count = 0;
  let t = text;
  for (const p of PATTERNS) {
    t = t.replace(p.re, (match) => {
      if (p.minDigits && (match.match(/\d/g) || []).length < p.minDigits) return match;
      count++;
      return p.label;
    });
  }
  t = t.replace(SIGN_OFF, (match, lead) => {
    count++;
    return `${lead} [NAME]`;
  });
  return { text: t, count };
};

return $input.all().map(({ json }) => {
  const { text, count } = redact(json.text);
  return { json: { ...json, text, pii_redactions: count } };
});

