// Never trust raw LLM output: validate every field against the allowed values,
// fall back safely, and flag anything suspicious for a human.
// Priority is a transparent formula, not an LLM opinion.
const ENUMS = {
  sentiment: ['positive', 'neutral', 'negative'],
  theme: ['usability', 'performance', 'integration', 'reporting_analytics', 'missing_feature', 'functional_defect', 'data_quality', 'documentation', 'pricing_licensing', 'other'],
  process_area: ['order_to_cash', 'procure_to_pay', 'record_to_report', 'plan_to_produce', 'hire_to_retire', 'cross_process'],
  urgency: ['low', 'medium', 'high'],
};
const URGENCY_POINTS = { low: 1, medium: 2, high: 3 };
const SENTIMENT_POINTS = { positive: 0, neutral: 1, negative: 2 };
const STRATEGIC_MULTIPLIER = 1.5;
const ESCALATION_THRESHOLD = 6;

const parseLlm = (json) => {
  let o = json.output ?? json.text ?? json;
  if (typeof o === 'string') {
    try { o = JSON.parse(o); } catch { return null; }
  }
  return o && typeof o === 'object' ? o : null;
};

const originals = $('Redact PII').all();
return $input.all().map((item, i) => {
  const src = originals[i]?.json ?? {};
  const llm = parseLlm(item.json);
  const issues = [];
  if (!llm) issues.push('unparseable_llm_output');
  const r = llm ?? {};
  if (r.feedback_id && r.feedback_id !== src.feedback_id) issues.push('feedback_id_mismatch');
  const pick = (field, fallback) => {
    if (ENUMS[field].includes(r[field])) return r[field];
    issues.push(`invalid_${field}`);
    return fallback;
  };
  const sentiment = pick('sentiment', 'neutral');
  const theme = pick('theme', 'other');
  const process_area = pick('process_area', 'cross_process');
  const urgency = pick('urgency', 'medium');
  const multiplier = src.customer_tier === 'strategic' ? STRATEGIC_MULTIPLIER : 1;
  const priority_score = Math.round((URGENCY_POINTS[urgency] + SENTIMENT_POINTS[sentiment]) * multiplier * 10) / 10;
  return {
    json: {
      feedback_id: src.feedback_id,
      customer: src.customer,
      customer_tier: src.customer_tier,
      source: src.source,
      received_at: src.received_at,
      text: src.text,
      sentiment,
      theme,
      process_area,
      urgency,
      is_feature_request: r.is_feature_request === true,
      summary: String(r.summary ?? '').slice(0, 240),
      suggested_action: String(r.suggested_action ?? ''),
      priority_score,
      escalate: priority_score >= ESCALATION_THRESHOLD,
      needs_human_review: issues.length > 0,
      validation_issues: issues,
      processed_at: new Date().toISOString(),
    },
  };
});

