// One digest per batch: what customers talk about, where it hurts, and what needs action now.
const rows = $input.all().map((i) => i.json);
const countBy = (key) => rows.reduce((acc, r) => {
  acc[r[key]] = (acc[r[key]] || 0) + 1;
  return acc;
}, {});
const themes = Object.entries(countBy('theme'))
  .map(([theme, count]) => {
    const negative = rows.filter((r) => r.theme === theme && r.sentiment === 'negative').length;
    return { theme, count, negative_share: Math.round((negative / count) * 100) / 100 };
  })
  .sort((a, b) => b.count - a.count || b.negative_share - a.negative_share);

return [{
  json: {
    generated_at: new Date().toISOString(),
    total_feedback: rows.length,
    by_sentiment: countBy('sentiment'),
    by_process_area: countBy('process_area'),
    top_themes: themes.slice(0, 5),
    feature_requests: rows.filter((r) => r.is_feature_request).length,
    escalations: rows
      .filter((r) => r.escalate)
      .sort((a, b) => b.priority_score - a.priority_score)
      .map((r) => ({ feedback_id: r.feedback_id, customer: r.customer, priority_score: r.priority_score, summary: r.summary })),
    needs_human_review: rows.filter((r) => r.needs_human_review).map((r) => r.feedback_id),
  },
}];
